// Command seed fills the local development database with a small but realistic dataset so the
// web client can be reviewed without clicking through a registration/upload flow first.
//
// It is deliberately idempotent: every write carries a "seed:" idempotency key or is naturally
// upsert-like, so `make seed` can be re-run after a failure without duplicating content.
//
// Videos are ordinary files under uploads/videos/seed (generated by scripts/seed_media.sh), which
// keeps this program free of any ffmpeg dependency.
package main

import (
	"context"
	"flag"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"strings"

	domainaccount "github.com/Tidehyc/gorangefeed/internal/domain/account"
	"github.com/Tidehyc/gorangefeed/internal/infra/config"
	"github.com/Tidehyc/gorangefeed/internal/infra/logger"
	"github.com/Tidehyc/gorangefeed/internal/infra/mysql"
	"github.com/Tidehyc/gorangefeed/internal/infra/redis"
	persistenceaccount "github.com/Tidehyc/gorangefeed/internal/infra/persistence/account"
	persistencefeed "github.com/Tidehyc/gorangefeed/internal/infra/persistence/feed"
	persistenceinteraction "github.com/Tidehyc/gorangefeed/internal/infra/persistence/interaction"
	persistencerelation "github.com/Tidehyc/gorangefeed/internal/infra/persistence/relation"
	persistencevideo "github.com/Tidehyc/gorangefeed/internal/infra/persistence/video"
	serviceinteraction "github.com/Tidehyc/gorangefeed/internal/service/interaction"
	servicerelation "github.com/Tidehyc/gorangefeed/internal/service/relation"
	servicevideo "github.com/Tidehyc/gorangefeed/internal/service/video"
)

const (
	demoPassword = "Passw0rd!"
	uploadsRoot  = "uploads"
	mediaPrefix  = "/media"
	seedSalt     = "v1"
)

type seedUser struct {
	username string
	nickname string
	bio      string
}

var users = []seedUser{
	{"alice", "Alice 爱旅行", "带着相机到处跑，记录山海与日常。"},
	{"bob", "Bob 的干饭日记", "人生苦短，先吃甜点。"},
	{"carol", "Carol 城市漫游", "在高楼之间寻找老街。"},
	{"dave", "Dave 慢慢看", "只看，不发，偶尔点赞。"},
	{"erin", "Erin 的猫", "家里有两只猫，一只叫拿铁，一只叫摩卡。"},
	{"frank", "Frank 在路上", "周末徒步爱好者。"},
}

type seedVideo struct {
	file    string
	author  string
	title   string
	desc    string
	tags    []string
	minutes int // duration in seconds, kept small so the clips stay light
}

var catalog = []seedVideo{
	{"travel-01.mp4", "alice", "海边的日落，是免费的浪漫", "傍晚六点的海岸线，风把云吹成了橘色。原片直出，没有调色。", []string{"旅行", "海边", "日落"}, 8},
	{"travel-02.mp4", "alice", "山间公路的第七个弯道", "无人机起飞前先看风向。这条路开过七次，每次的光都不一样。", []string{"旅行", "公路", "风景"}, 10},
	{"travel-03.mp4", "alice", "古镇的清晨比白天好看", "六点半的古镇没有游客，只有开门的吱呀声和豆浆铺子的热气。", []string{"旅行", "古镇", "清晨"}, 9},
	{"travel-04.mp4", "alice", "雪山脚下的蓝色湖泊", "海拔 3800 米，风很大，值得。", []string{"旅行", "雪山", "湖泊"}, 11},
	{"travel-05.mp4", "alice", "露营的第一杯咖啡", "帐篷外是森林，帐篷里是手冲。这才是周末的意义。", []string{"旅行", "露营", "咖啡"}, 7},
	{"travel-06.mp4", "alice", "坐绿皮火车去看海", "慢车有慢车的风景，车窗就是最好的取景框。", []string{"旅行", "火车", "海边"}, 12},
	{"food-01.mp4", "bob", "这家面馆的汤头熬了 12 小时", "藏在巷子里的老店，每天只卖 200 碗，卖完就收摊。", []string{"美食", "探店", "面食"}, 9},
	{"food-02.mp4", "bob", "自制杨枝甘露，成本不到 8 块", "芒果要选熟的，西米要过凉水，椰浆最后放。", []string{"美食", "甜品", "教程"}, 10},
	{"city-01.mp4", "carol", "CBD 的另一种打开方式", "下班后的写字楼群，比白天更安静，也更好看。", []string{"城市", "夜景", "摄影"}, 8},
	{"city-02.mp4", "carol", "老街的最后一间修表铺", "师傅修了四十年表，店里的钟永远停在下午四点。", []string{"城市", "老街", "人文"}, 11},
	{"pet-01.mp4", "erin", "猫咪第一次看见黄瓜", "拿铁的反应比我想象中冷静，摩卡直接起飞。", []string{"宠物", "猫", "搞笑"}, 6},
	{"pet-02.mp4", "dave", "小区里的大橘又来蹭饭了", "每天准时七点出现在楼下，比我的闹钟还准。", []string{"宠物", "猫", "日常"}, 7},
}

var commentTexts = []string{
	"这个画面太舒服了，收藏了",
	"请问具体位置在哪里？想去",
	"拍得真好，求设备型号",
	"看了三遍，还是很喜欢",
	"博主好会拍，学习一下",
	"这就是我想去的地方",
	"配乐和画面很搭",
	"看完心情变好了",
}

func main() {
	var configPath string
	flag.StringVar(&configPath, "config", "configs/config.yaml", "path to configuration file")
	flag.Parse()

	l := logger.Init("info", "json")
	cfg, err := config.Load(configPath)
	if err != nil {
		l.Error("failed to load configuration", "error", err)
		os.Exit(1)
	}

	db, err := mysql.New(&cfg.MySQL)
	if err != nil {
		l.Error("failed to connect to MySQL", "error", err)
		os.Exit(1)
	}
	rdb, err := redis.New(&cfg.Redis)
	if err != nil {
		l.Error("failed to connect to Redis", "error", err)
		os.Exit(1)
	}

	ctx := context.Background()
	accountRepo := persistenceaccount.NewRepository(db)
	videoRepo := persistencevideo.NewRepository(db)
	interactionRepo := persistenceinteraction.NewRepository(db)
	relationRepo := persistencerelation.NewRepository(db)
	timelineRepo := persistencefeed.NewTimelineStore(rdb)

	videoSvc := servicevideo.NewService(videoRepo, accountRepo)
	interactionSvc := serviceinteraction.NewService(interactionRepo, videoRepo, accountRepo)
	relationSvc := servicerelation.NewService(relationRepo, accountRepo)

	ids := make(map[string]int64, len(users))
	for _, u := range users {
		existing, err := accountRepo.FindByUsername(ctx, u.username)
		if err == nil && existing != nil {
			ids[u.username] = existing.ID
			continue
		}

		hash, err := domainaccount.HashPassword(demoPassword)
		if err != nil {
			l.Error("failed to hash demo password", "error", err)
			os.Exit(1)
		}
		user := &domainaccount.User{
			Username:     u.username,
			PasswordHash: hash,
			Nickname:     u.nickname,
			Bio:          u.bio,
			AvatarURL:    "",
			Status:       domainaccount.UserStatusActive,
			Role:         domainaccount.RoleUser,
		}
		if err := accountRepo.Create(ctx, user); err != nil {
			l.Error("failed to create demo user", "username", u.username, "error", err)
			os.Exit(1)
		}
		ids[u.username] = user.ID
		l.Info("created demo user", "username", u.username, "id", user.ID)
	}

	// Follow graph: alice <-> bob and alice <-> carol are mutual (is_friend=true); dave follows
	// nobody, so the following feed has a genuine empty state to show.
	for _, edge := range [][2]string{
		{"alice", "bob"}, {"bob", "alice"},
		{"alice", "carol"}, {"carol", "alice"},
		{"bob", "carol"}, {"erin", "alice"}, {"frank", "alice"},
	} {
		if err := relationSvc.Follow(ctx, ids[edge[0]], ids[edge[1]]); err != nil {
			l.Error("failed to seed follow", "from", edge[0], "to", edge[1], "error", err)
		}
	}

	// Deterministic randomness: re-running the seeder must not reshuffle the engagement numbers.
	rng := rand.New(rand.NewSource(20261106))
	created := 0
	skipped := 0

	for index, item := range catalog {
		playURL := fmt.Sprintf("%s/videos/seed/%s", mediaPrefix, item.file)
		if _, err := os.Stat(filepath.Join(uploadsRoot, "videos", "seed", item.file)); err != nil {
			l.Warn("media file missing, run scripts/seed_media.sh first", "file", item.file)
			skipped++
			continue
		}

		coverURL := ""
		if _, err := os.Stat(filepath.Join(uploadsRoot, "covers", "seed", strings.Replace(item.file, ".mp4", ".jpg", 1))); err == nil {
			coverURL = fmt.Sprintf("%s/covers/seed/%s", mediaPrefix, strings.Replace(item.file, ".mp4", ".jpg", 1))
		}

		detail, err := videoSvc.Publish(
			ctx,
			ids[item.author],
			item.title,
			item.desc,
			playURL,
			coverURL,
			item.minutes*1000,
			fmt.Sprintf("seed:%s:video:%s", seedSalt, item.file),
			item.tags,
		)
		if err != nil {
			l.Error("failed to publish seed video", "file", item.file, "error", err)
			os.Exit(1)
		}
		videoID := detail.Video.ID
		created++

		// The feed timeline lives in Redis; publishing through the service writes MySQL only, so
		// the seed data has to be appended explicitly (the API does this via publish hooks).
		if err := timelineRepo.Append(ctx, videoID); err != nil {
			l.Warn("failed to append seed video to the timeline", "video_id", videoID, "error", err)
		}

		// Engagement: a handful of likes and comments, always from other accounts so the author's
		// own counts stay meaningful.
		for _, u := range users {
			if u.username == item.author {
				continue
			}
			if rng.Intn(4) == 0 {
				if err := interactionSvc.LikeVideo(ctx, ids[u.username], videoID); err != nil {
					l.Warn("failed to seed like", "video_id", videoID, "error", err)
				}
			}
		}

		commentCount := rng.Intn(4) // 0..3 top-level comments
		for c := 0; c < commentCount; c++ {
			commenter := users[rng.Intn(len(users))]
			text := commentTexts[(index+c)%len(commentTexts)]
			comment, _, err := interactionSvc.CreateComment(
				ctx,
				ids[commenter.username],
				videoID,
				0,
				text,
				fmt.Sprintf("seed:%s:comment:%s:%d", seedSalt, item.file, c),
			)
			if err != nil {
				l.Warn("failed to seed comment", "video_id", videoID, "error", err)
				continue
			}

			// One reply on the first comment of each video exercises the parent_id path.
			if c == 0 && comment != nil && comment.Comment != nil {
				replier := users[(index+2)%len(users)]
				if _, _, err := interactionSvc.CreateComment(
					ctx,
					ids[replier.username],
					videoID,
					comment.Comment.ID,
					"同感！+1",
					fmt.Sprintf("seed:%s:reply:%s:%d", seedSalt, item.file, c),
				); err != nil {
					l.Warn("failed to seed reply", "video_id", videoID, "error", err)
				}
			}
		}
	}

	fmt.Printf("\nSeed finished: %d videos ready (%d skipped, media missing), %d demo accounts.\n", created, skipped, len(users))
	fmt.Printf("Demo login: alice / %s (same password for bob, carol, dave, erin, frank)\n", demoPassword)
	if skipped > 0 {
		fmt.Println("Some media files are missing. Generate them with: bash scripts/seed_media.sh")
	}
}
